import type { SVGProps } from "react";

// Icons exported from the Figma board. Decorative only: every icon sits next
// to a text label or inside a labelled button. All use currentColor. The tab
// bar's illustrated icons are SVG files in src/assets/tabs.

type IconProps = SVGProps<SVGSVGElement> & { size?: number };

function Line({ size = 24, viewBox = "0 0 24 24", children, ...props }: IconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox={viewBox}
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      {children}
    </svg>
  );
}

function Filled({ size = 24, viewBox = "0 0 24 24", children, ...props }: IconProps) {
  return (
    <svg width={size} height={size} viewBox={viewBox} fill="currentColor" aria-hidden="true" focusable="false" {...props}>
      {children}
    </svg>
  );
}

